#!/usr/bin/env python3
"""
The Ed25519 public key is embedded by admin_generator.py. This app does not
change ETAP policies; system autostart installation is explicit and reversible.
"""
import base64
import ctypes
import ctypes.util
import json
import os
import re
import shutil
import subprocess
import sys
import tkinter as tk
from ctypes import wintypes
from pathlib import Path
from tkinter import messagebox

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

FONT_FAMILY = "Segoe UI" if os.name == "nt" else "DejaVu Sans"
PUBLIC_KEY_PEM = b'-----BEGIN PUBLIC KEY-----\nMCowBQYDK2VwAyEAUp714gaysEk5DcM2y2dJ97tGABmeEyuP3LHJ1G9917I=\n-----END PUBLIC KEY-----\n'  # Yönetici anahtarı
REQUIRED_FIELDS = {"schema_version", "teacher_name", "key_id", "issued_at"}
KEY_FILENAME = "teacher-key.json"
MAX_KEY_FILE_BYTES = 64 * 1024  # gerçek dosya ~500 bayt; büyük dosya arayüzü dondurmasın
MOUNT_PREFIXES = ("/media/", "/run/media/", "/mnt/")
CREDIT_TEXT = "by Kağan Yavuz"  # imza
LOGO_PNG_B64 = {  # okul logosu
    220: "",
    280: "",
    330: "",
}

def canonical_payload(payload):
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

def verify_file(key_file):
    if Path(key_file).stat().st_size > MAX_KEY_FILE_BYTES:
        raise ValueError("Dosya beklenenden çok büyük.")
    document = json.loads(Path(key_file).read_text(encoding="utf-8"))
    payload = document["payload"]
    signature = base64.b64decode(document["signature"], validate=True)
    if not isinstance(payload, dict) or set(payload) != REQUIRED_FIELDS:
        raise ValueError("Dosyanın biçimi beklenenden farklı.")
    if payload["schema_version"] != 1:
        raise ValueError("Dosya sürümü desteklenmiyor.")
    if not all(isinstance(payload[key], str) and payload[key].strip() for key in ("teacher_name", "key_id", "issued_at")):
        raise ValueError("Dosyadaki bilgiler eksik.")
    public_key = serialization.load_pem_public_key(PUBLIC_KEY_PEM)
    if not isinstance(public_key, Ed25519PublicKey):
        raise ValueError("Pano programındaki açık anahtar Ed25519 değil.")
    public_key.verify(signature, canonical_payload(payload))
    return payload

def linux_key_files():
    """Find the key file at Linux removable-media mount points."""
    try:
        mount_lines = Path("/proc/mounts").read_text(encoding="utf-8").splitlines()
    except OSError:
        return
    seen = set()
    for line in mount_lines:
        columns = line.split()
        if len(columns) < 2:
            continue
        target = re.sub(r"\\([0-7]{3})", lambda match: chr(int(match.group(1), 8)), columns[1])
        if not target.startswith(MOUNT_PREFIXES):
            continue
        candidate = Path(target) / KEY_FILENAME
        if candidate not in seen:
            seen.add(candidate)
            yield candidate

def windows_key_files():
    """Check mounted Windows drive roots for the signed key file."""
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.GetLogicalDrives.restype = ctypes.c_uint32
    kernel32.GetDriveTypeW.argtypes = (ctypes.c_wchar_p,)
    kernel32.GetDriveTypeW.restype = ctypes.c_uint
    drive_mask = kernel32.GetLogicalDrives()
    for drive_number in range(26):
        if drive_mask & (1 << drive_number):
            drive_root = f"{chr(ord('A') + drive_number)}:\\"
            drive_type = kernel32.GetDriveTypeW(drive_root)
            # Include removable media and fixed USB drives; signatures do not
            # prove that the signed file is physically on a USB device.
            if drive_type in (2, 3):
                yield Path(drive_root) / KEY_FILENAME

def mounted_key_files():
    """Find key files using the current operating system's drive list."""
    if os.name == "nt":
        yield from windows_key_files()
    else:
        yield from linux_key_files()

def find_authorized_teacher():
    for key_file in mounted_key_files():
        try:
            return verify_file(key_file)
        except (OSError, ValueError, KeyError, TypeError, InvalidSignature):
            continue
    return None

class _XAttrs(ctypes.Structure):
    """Xlib XWindowAttributes yapısı."""
    _fields_ = [
        ("x", ctypes.c_int), ("y", ctypes.c_int), ("width", ctypes.c_int), ("height", ctypes.c_int),
        ("border_width", ctypes.c_int), ("depth", ctypes.c_int), ("visual", ctypes.c_void_p),
        ("root", ctypes.c_ulong), ("klass", ctypes.c_int), ("bit_gravity", ctypes.c_int),
        ("win_gravity", ctypes.c_int), ("backing_store", ctypes.c_int),
        ("backing_planes", ctypes.c_ulong), ("backing_pixel", ctypes.c_ulong),
        ("save_under", ctypes.c_int), ("colormap", ctypes.c_ulong), ("map_installed", ctypes.c_int),
        ("map_state", ctypes.c_int), ("all_event_masks", ctypes.c_long),
        ("your_event_mask", ctypes.c_long), ("do_not_propagate_mask", ctypes.c_long),
        ("override_redirect", ctypes.c_int), ("screen", ctypes.c_void_p),
    ]


class XGuard:
    """Linux/X11: pencerenin GERÇEK durumunu X sunucusundan okuyup düzeltir.

    Tk, pencere dışarıdan gizlenirse/taşınırsa bunu her zaman fark etmez; bu yüzden
    Xlib'e doğrudan bağlanıp gizleme, taşıma, boyut değişikliği ve arkaya atmayı geri alırız."""

    def __init__(self):
        self.lib = None
        self.display = None
        try:
            name = ctypes.util.find_library("X11")
            if not name:
                return
            lib = ctypes.CDLL(name)
            lib.XOpenDisplay.argtypes = (ctypes.c_char_p,)
            lib.XOpenDisplay.restype = ctypes.c_void_p
            lib.XGetWindowAttributes.argtypes = (ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(_XAttrs))
            lib.XGetWindowAttributes.restype = ctypes.c_int
            lib.XMapWindow.argtypes = (ctypes.c_void_p, ctypes.c_ulong)
            lib.XMoveResizeWindow.argtypes = (ctypes.c_void_p, ctypes.c_ulong, ctypes.c_int, ctypes.c_int, ctypes.c_uint, ctypes.c_uint)
            lib.XRaiseWindow.argtypes = (ctypes.c_void_p, ctypes.c_ulong)
            lib.XFlush.argtypes = (ctypes.c_void_p,)
            display = lib.XOpenDisplay(None)
            if display:
                self.lib, self.display = lib, display
        except (OSError, AttributeError):
            self.lib = self.display = None

    def enforce(self, window_id, width, height):
        """Pencereyi görünür, ekranı kaplar ve en üstte tutar. Düzeltme yapıldıysa True döner."""
        if not self.display:
            return False
        attrs = _XAttrs()
        if not self.lib.XGetWindowAttributes(self.display, window_id, ctypes.byref(attrs)):
            return False
        changed = False
        if attrs.map_state == 0:  # IsUnmapped
            self.lib.XMapWindow(self.display, window_id)
            changed = True
        if (attrs.x, attrs.y, attrs.width, attrs.height) != (0, 0, width, height):
            self.lib.XMoveResizeWindow(self.display, window_id, 0, 0, width, height)
            changed = True
        self.lib.XRaiseWindow(self.display, window_id)
        self.lib.XFlush(self.display)
        return changed

class BoardApp:
    def __init__(self, root):
        self.root = root
        self.is_locked = True
        root.title("Öğretmen USB Erişim Kilidi")
        root.configure(bg="#10243a")
        root.overrideredirect(True)  # başlık/küçültme düğmesi yok; pencere yöneticisi taşıyamaz
        self.apply_lock_geometry()
        root.update_idletasks()
        scale = max(0.85, min(root.winfo_screenheight() / 1080, 1.5))
        root.protocol("WM_DELETE_WINDOW", self.keep_open)
        root.bind("<Alt-F4>", self.keep_open)
        root.bind("<Escape>", self.keep_open)
        root.bind("<FocusOut>", self.restore_lock_window)
        root.bind("<Unmap>", self.restore_lock_window)
        self.xguard = XGuard() if os.name != "nt" else None
        root.after(100, self.activate_lock)
        root.after(100, self.enforce_lock)

        frame = tk.Frame(root, bg="#10243a")
        frame.place(relx=0.5, rely=0.5, anchor="center")
        if LOGO_PNG_B64:
            try:
                logo_size = 220 if scale < 1.15 else 280 if scale < 1.35 else 330
                self.logo = tk.PhotoImage(data=LOGO_PNG_B64[logo_size])
                tk.Label(frame, image=self.logo, bg="#10243a").pack(pady=(0, round(24 * scale)))
            except tk.TclError:
                pass
        tk.Label(frame, text="ETAP • ERİŞİM KİLİDİ", font=(FONT_FAMILY, round(15 * scale), "bold"), bg="#10243a", fg="#91c8ff").pack(pady=(0, round(22 * scale)))
        tk.Label(frame, text="Tahtayı kullanmak için\nimzalı USB takın...", font=(FONT_FAMILY, round(28 * scale), "bold"), bg="#10243a", fg="white", justify="center").pack(pady=(0, round(18 * scale)))
        self.status = tk.StringVar(value="USB bekleniyor…")
        tk.Label(frame, textvariable=self.status, font=(FONT_FAMILY, round(13 * scale)), bg="#10243a", fg="#cbd5e1").pack()
        tk.Label(frame, text="USB çıkarılınca erişim yeniden kilitlenir.", font=(FONT_FAMILY, round(10 * scale)), bg="#10243a", fg="#94a3b8").pack(pady=(round(22 * scale), 0))

        tk.Label(root, text=CREDIT_TEXT, font=(FONT_FAMILY, round(11 * scale)), bg="#10243a", fg="#979797").place(relx=1.0, rely=1.0, anchor="se", x=-23, y=-18)

        root.after(500, self.check_usb)

    def activate_lock(self):
        if self.is_locked:
            self.take_grab()

    def take_grab(self):
        """Klavye ve fareyi tamamen bu pencereye bağlar.

        Linux/X11'de küresel kilit (grab -global) Alt+F4, Super, Super+D gibi
        pencere yöneticisi kısayollarının çalışmasını engeller."""
        try:
            if os.name == "nt":
                if self.root.grab_current() is None:
                    self.root.grab_set()
            elif self.root.grab_status() != "global":
                self.root.grab_set_global()
            self.root.focus_force()
        except tk.TclError:
            pass

    def keep_open(self, _event=None):
        return "break"

    def restore_lock_window(self, _event=None):
        if self.is_locked:
            self.root.after(30, self.bring_to_front)

    def apply_lock_geometry(self):
        self.root.geometry(f"{self.root.winfo_screenwidth()}x{self.root.winfo_screenheight()}+0+0")
        self.root.attributes("-topmost", True)

    def native_restore(self):
        """Windows: pencere küçültüldüyse/arkaya atıldıysa doğrudan Win32 ile geri getirir."""
        if os.name != "nt":
            return
        user32 = ctypes.windll.user32
        user32.GetParent.argtypes = (wintypes.HWND,)
        user32.GetParent.restype = wintypes.HWND
        user32.IsIconic.argtypes = (wintypes.HWND,)
        user32.ShowWindow.argtypes = (wintypes.HWND, ctypes.c_int)
        user32.SetForegroundWindow.argtypes = (wintypes.HWND,)
        user32.SetWindowPos.argtypes = (wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_uint)
        hwnd = user32.GetParent(self.root.winfo_id()) or self.root.winfo_id()
        if user32.IsIconic(hwnd):
            user32.ShowWindow(hwnd, 9)  # SW_RESTORE
        # HWND_TOPMOST = -1, SWP_SHOWWINDOW = 0x0040
        user32.SetWindowPos(hwnd, -1, 0, 0, self.root.winfo_screenwidth(), self.root.winfo_screenheight(), 0x0040)
        user32.SetForegroundWindow(hwnd)

    def enforce_lock(self):
        """Kilitliyken pencere küçültülür/kayarsa/arkaya düşerse her 0,1 sn'de geri getirir."""
        try:
            if self.is_locked:
                self.native_restore()
                screen = (self.root.winfo_screenwidth(), self.root.winfo_screenheight())
                if self.xguard is not None and self.xguard.enforce(self.root.winfo_id(), *screen):
                    # Pencere gizlenip geri açılınca X sunucusu klavye/fare kilidini bırakır: yeniden al.
                    self.root.grab_release()
                if self.root.state() != "normal":
                    self.root.deiconify()
                current = (self.root.winfo_x(), self.root.winfo_y(), self.root.winfo_width(), self.root.winfo_height())
                if current != (0, 0) + screen:
                    self.apply_lock_geometry()
                self.root.lift()
                self.take_grab()
        except Exception:
            pass  # bekçi döngüsü hiçbir koşulda durmamalı
        self.root.after(100, self.enforce_lock)

    def bring_to_front(self):
        if self.is_locked:
            try:
                self.root.deiconify()
                self.apply_lock_geometry()
                self.root.lift()
                self.root.focus_force()
                self.native_restore()
            except Exception:
                pass

    def check_usb(self):
        payload = find_authorized_teacher()
        if payload is not None:
            if self.is_locked:
                self.is_locked = False
                try:
                    self.root.grab_release()
                    self.root.attributes("-topmost", False)
                except tk.TclError:
                    pass
                # Yakalama bırakıldıktan sonra kısa bekleyip gizle: dokunmatik girişi takılı kalmasın.
                self.root.after(200, lambda: None if self.is_locked else self.root.withdraw())
            self.status.set(f"Yetkili USB doğrulandı: {payload['teacher_name']}")
        else:
            if not self.is_locked:
                self.is_locked = True
                self.root.deiconify()
                self.apply_lock_geometry()
                self.root.lift()
                self.take_grab()
            self.status.set("USB bekleniyor…")
        self.root.after(1000, self.check_usb)

APP_NAME = "etap-ogretmen-usb-kilidi"

def is_admin():
    if os.name == "nt":
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    return os.geteuid() == 0

GDM_CONFIGS = (Path("/etc/gdm3/daemon.conf"), Path("/etc/gdm3/custom.conf"), Path("/etc/gdm/custom.conf"))


def force_xorg(enable=True):
    """GDM'de Wayland'ı kapatır (tüm kullanıcılar Xorg ile açılır) ya da yedekten geri alır.

    Wayland oturumunda Super, Super+D ve dokunmatik hareketleri uygulama engelleyemez."""
    for conf in GDM_CONFIGS:
        if not conf.exists():
            continue
        backup = conf.with_name(conf.name + ".etap-yedek")
        if not enable:
            if backup.exists():
                shutil.copyfile(backup, conf)
                backup.unlink()
            return
        if not backup.exists():
            shutil.copyfile(conf, backup)
        lines = conf.read_text(encoding="utf-8").splitlines()
        new_line = "WaylandEnable=false"
        index = next((i for i, line in enumerate(lines) if re.match(r"\s*WaylandEnable\s*=", line)), None)
        if index is None:
            index = next((i for i, line in enumerate(lines) if re.match(r"\s*#\s*WaylandEnable\s*=", line)), None)
        if index is not None:
            lines[index] = new_line
        else:
            header = next((i for i, line in enumerate(lines) if line.strip() == "[daemon]"), None)
            if header is None:
                lines += ["[daemon]", new_line]
            else:
                lines.insert(header + 1, new_line)
        conf.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return

def system_copy():
    """Tüm kullanıcılar için kurulan kopyanın yolu."""
    if os.name == "nt":
        return Path(os.environ.get("ProgramData", r"C:\ProgramData")) / "EtapUsbKilidi" / "board_verifier.py"
    return Path("/opt/etap-usb-kilidi/board_verifier.py")

def autostart_entry(per_user=False):
    """Otomatik başlatma dosyasının yolu (per_user=False: tüm kullanıcılar)."""
    if os.name == "nt":
        base = Path(os.environ["APPDATA" if per_user else "ProgramData"])
        return base / "Microsoft" / "Windows" / "Start Menu" / "Programs" / "Startup" / f"{APP_NAME}.vbs"
    if per_user:
        return Path.home() / ".config" / "autostart" / f"{APP_NAME}.desktop"
    return Path("/etc/xdg/autostart") / f"{APP_NAME}.desktop"

def install_autostart(remove=False, per_user=False):
    source = Path(__file__).resolve()
    entry = autostart_entry(per_user)
    target_dir = None
    if not per_user:
        if not is_admin():
            raise PermissionError("Yönetici yetkisi gerekli.")
        if os.name == "nt":
            target_dir = Path(os.environ.get("ProgramData", r"C:\ProgramData")) / "EtapUsbKilidi"
        else:
            target_dir = Path("/opt/etap-usb-kilidi")
    if remove:
        entry.unlink(missing_ok=True)
        if target_dir:
            shutil.rmtree(target_dir, ignore_errors=True)
            if os.name != "nt":
                try:
                    force_xorg(False)
                except OSError:
                    pass
        return
    target = source
    if target_dir:
        target_dir.mkdir(parents=True, exist_ok=True)
        target = target_dir / "board_verifier.py"
        if source != target.resolve():
            shutil.copyfile(source, target)
        if os.name != "nt":
            target_dir.chmod(0o755)
            target.chmod(0o644)
            try:
                force_xorg()
            except OSError:
                pass
    entry.parent.mkdir(parents=True, exist_ok=True)
    if os.name == "nt":
        exe = Path(sys.executable)
        pythonw = exe.with_name("pythonw.exe")  # konsol penceresi açmaz
        if not pythonw.exists():
            pythonw = exe
        entry.write_text(f'CreateObject("WScript.Shell").Run """{pythonw}"" ""{target}""", 0, False\r\n', encoding="mbcs")
    else:
        entry.write_text(
            "[Desktop Entry]\n"
            "Type=Application\n"
            "Name=Öğretmen USB Kilidi\n"
            f'Exec="{sys.executable}" "{target}"\n'
            "Terminal=false\n"
            "X-GNOME-Autostart-enabled=true\n"
            "X-GNOME-Autostart-Delay=3\n",
            encoding="utf-8",
        )
        entry.chmod(0o644)

def ensure_autostart():
    """Normal çalıştırmada otomatik başlatma kurulu değilse kurar; komut gerekmez."""
    source = Path(__file__).resolve()
    installed = autostart_entry().exists() or autostart_entry(per_user=True).exists()
    copy = system_copy()
    outdated = False
    if installed and copy.exists() and source != copy.resolve():
        try:
            outdated = copy.read_bytes() != source.read_bytes()  # yeni sürüm: kurulu kopyayı yenile
        except OSError:
            pass
    if installed and not outdated:
        return
    try:
        if is_admin():
            install_autostart()
        elif os.name == "nt":
            # UAC onayı ister; reddedilirse yalnızca bu kullanıcı için kurulur.
            result = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, f'"{source}" --install', None, 0)
            if result <= 32:
                install_autostart(per_user=True)
        else:
            # Parola penceresi, kilit ekranı açılmadan önce gösterilir.
            subprocess.run(["pkexec", sys.executable, str(source), "--install"], check=True)
    except (OSError, subprocess.SubprocessError):
        try:
            install_autostart(per_user=True)
        except OSError:
            pass

if __name__ == "__main__":
    if "--remove" in sys.argv:
        for user_only in (False, True):
            try:
                install_autostart(remove=True, per_user=user_only)
            except OSError as exc:
                print("Kaldırılamadı:", exc)
        raise SystemExit(0)
    if "--install" in sys.argv:
        try:
            install_autostart()
        except OSError as exc:
            raise SystemExit(str(exc))
        raise SystemExit(0)
    ensure_autostart()
    window = tk.Tk()
    BoardApp(window)
    window.mainloop()